/**
 * @method
 * @name scwin.viewFormList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.viewFormList = function () {
    /* sdd-asis-lifecycle:begin viewFormList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let all_checked = true;
    for (let i = 0; i < $c.util.getComponent('ipt_editClass').length; i++) {
        if ($c.util.getComponent(["ipt_editClass", "ipt_editClass_2", "ipt_editClass_3"][i]).getValue() === "TEMP") {
            continue;
        }
        const prefix = $c.util.getComponent(["ipt_editClass", "ipt_editClass_2", "ipt_editClass_3"][i]).getValue();
        if ((String($c.util.getComponent(["ipt_editClass", "ipt_editClass_2", "ipt_editClass_3"][i]).getValue() || '') !== '')) {
            scwin.displaySubEditList(prefix, "block");
        } else {
            all_checked = false;
            scwin.displaySubEditList(prefix, "none");
        }
    }
    $c.util.getComponent("ipt_allEdit").setValue(all_checked);
    /* sdd-asis-lifecycle:end */
};


